const item = $input.first().json;
const exec = item.execution || {};
const wf = item.workflow || {};
const err = exec.error || {};

const execId = exec.id || 'N/A';
const wfName = wf.name || 'Unknown Workflow';
const wfId = wf.id || 'N/A';
const lastNode = exec.lastNodeExecuted || err.node || 'Unknown Node';
const errMsg = String(err.message || 'Execution halted unexpectedly').slice(0, 300);
const nowIso = new Date().toISOString();
const execUrl = `http://100.110.242.47:5678/execution/${execId}`;

const tgText = `🚨 <b>n8n Enterprise Workflow Incident</b>
` +
  `🕒 <code>${nowIso}</code>

` +
  `• <b>Workflow:</b> <code>${wfName}</code>
` +
  `• <b>Failed Node:</b> <code>${lastNode}</code>
` +
  `• <b>Error:</b> <code>${errMsg}</code>
` +
  `• <b>Execution:</b> <a href="${execUrl}">#${execId} (Review Run)</a>`;

return [{
  json: {
    execId,
    wfName,
    wfId,
    lastNode,
    errMsg,
    timestamp: nowIso,
    execUrl,
    telegram_message: tgText,
    chat_id: '8843884232'
  }
}];
